// PECS - src produkuje, dest konsumuje:
static <T> void copy(List<? super T> dest, List<? extends T> src) {
    for (int i = 0; i < src.size(); i++) dest.set(i, src.get(i));
}
List<Integer> zrodlo = List.of(1,2,3);
List<Number> cel = new ArrayList<>(List.of(0,0,0));
copy(cel, zrodlo); // dziala - Number jest nadtypem Integer

// Niezmiennosc generykow:
List<Integer> intList = new ArrayList<>(List.of(1,2,3));
// List<Number> n = intList; // BLAD KOMPILACJI
List<? extends Number> readOnly = intList; // OK - tylko odczyt

// Kowariancja tablic - niebezpieczna:
